"""Build a public-domain MedlinePlus gene directory plus curated NCI starting points."""
import json,xml.etree.ElementTree as E,hashlib,re,html,sys
from pathlib import Path
root=Path(__file__).resolve().parents[1];src=Path(sys.argv[1]);r=E.parse(src).getroot();ns={'g':r.tag.split('}')[0][1:]}
h=html.escape
order='CDH1 BRCA1 BRCA2 PALB2 MLH1 MSH2 MSH6 PMS2 EPCAM APC MUTYH TP53 PTEN STK11 ATM CHEK2 RAD51C RAD51D BRIP1 CDKN2A BAP1 VHL RET MEN1 NF1 DICER1 FH FLCN SDHB SDHD CTNNA1 POLE POLD1 NTHL1 SMAD4 BMPR1A HOXB13 RB1 TSC1 TSC2'.split()
focus=['Diffuse gastric and lobular breast cancer','Hereditary breast and ovarian cancer','Breast, ovarian, prostate and pancreatic cancer','Breast, pancreatic and ovarian cancer','Lynch syndrome','Lynch syndrome','Lynch syndrome','Lynch syndrome','Lynch syndrome from certain EPCAM deletions','Familial adenomatous polyposis','MUTYH-associated polyposis, usually with two pathogenic variants','Li-Fraumeni syndrome','PTEN hamartoma tumor syndrome','Peutz-Jeghers syndrome','Breast cancer susceptibility; two pathogenic variants can cause ataxia-telangiectasia','Breast cancer susceptibility; variant-specific interpretation matters','Ovarian and breast cancer susceptibility','Ovarian and breast cancer susceptibility','Ovarian cancer susceptibility','Melanoma and pancreatic cancer susceptibility','BAP1 tumor predisposition syndrome','Von Hippel-Lindau syndrome','Multiple endocrine neoplasia type 2','Multiple endocrine neoplasia type 1','Neurofibromatosis type 1','DICER1 tumor predisposition','Hereditary leiomyomatosis and renal cell cancer','Birt-Hogg-Dubé syndrome','Hereditary paraganglioma and pheochromocytoma','Hereditary paraganglioma and pheochromocytoma','Hereditary diffuse gastric cancer','Polymerase proofreading-associated polyposis','Polymerase proofreading-associated polyposis','NTHL1 tumor syndrome with two pathogenic variants','Juvenile polyposis and hereditary hemorrhagic telangiectasia','Juvenile polyposis','Hereditary prostate cancer susceptibility','Hereditary retinoblastoma','Tuberous sclerosis complex','Tuberous sclerosis complex']
assert len(focus)==len(order)
genes=[]
def txt(x):return ' '.join(''.join(x.itertext()).split()) if x is not None else ''
for x in r.findall('g:gene-summary',ns):
 symbol=x.findtext('g:gene-symbol',namespaces=ns);paras=[]
 for t in x.findall('g:text-list/g:text',ns):
  if t.findtext('g:text-role',namespaces=ns)=='function':
   body=t.find('g:html',ns)
   if body is not None:paras=[txt(p) for p in body if txt(p)]
 conditions=[{'name':c.findtext('g:name',namespaces=ns).strip(),'url':c.findtext('g:ghr-page',namespaces=ns)} for c in x.findall('g:related-health-condition-list/g:related-health-condition',ns)]
 genes.append({'symbol':symbol,'name':x.findtext('g:name',namespaces=ns),'url':x.findtext('g:ghr-page',namespaces=ns),'source':'MedlinePlus, National Library of Medicine','summary':paras[0] if paras else 'Read the source gene overview for details.','conditions':conditions,'aliases':[txt(v) for v in x.findall('g:synonym-list/g:synonym',ns)],'reviewed':x.findtext('g:reviewed',default='',namespaces=ns),'kind':'source_excerpt'})
breast='https://www.cancer.gov/types/breast/hp/breast-ovarian-genetics-pdq';colon='https://www.cancer.gov/types/colorectal/hp/colorectal-genetics-pdq';gastric='https://www.cancer.gov/publications/pdq/information-summaries/genetics/hereditary-diffuse-gastric-cancer-hp-pdq'
extra={
'ERBB2':('erb-b2 receptor tyrosine kinase 2','ERBB2 encodes the HER2 protein. In tumors, extra gene copies can lead to excess HER2 protein and may influence treatment planning. A tumor biomarker result alone does not establish an inherited cancer syndrome.','https://training.seer.cancer.gov/breast/evaluation/biomarkers.html',['HER2','HER-2','HER2/neu','NEU']),
'PALB2':('partner and localizer of BRCA2','Inherited pathogenic variants can increase breast, pancreatic and ovarian cancer risk. A genetics team can interpret the exact variant and family history.','https://www.cancer.gov/publications/pdq/information-summaries/genetics/palb2-hp-pdq',['FANCN']),
'CHEK2':('checkpoint kinase 2','Certain inherited pathogenic variants increase breast cancer risk. Risk differs by variant and family history.',breast,['CHK2']),
'RAD51C':('RAD51 paralog C','Inherited pathogenic variants are associated with ovarian and breast cancer susceptibility.',breast,['FANCO']),
'RAD51D':('RAD51 paralog D','Inherited pathogenic variants are associated with ovarian and breast cancer susceptibility.',breast,[]),
'BRIP1':('BRCA1 interacting helicase 1','Inherited pathogenic variants increase ovarian cancer risk. BRIP1 should not be treated as an established moderate- or high-risk breast cancer gene.',breast,['FANCJ','BACH1']),
'CTNNA1':('catenin alpha 1','Some inherited pathogenic variants are associated with hereditary diffuse gastric cancer. Risk estimates and management evidence are less established than for CDH1.',gastric,[]),
'POLE':('DNA polymerase epsilon catalytic subunit','Specific proofreading-domain pathogenic variants can cause polymerase proofreading-associated polyposis. Not every POLE variant carries this hereditary risk.',colon,[]),
'POLD1':('DNA polymerase delta 1','Specific proofreading-domain pathogenic variants can cause polymerase proofreading-associated polyposis. Interpretation depends on the exact variant.',colon,[]),
'NTHL1':('nth like DNA glycosylase 1','NTHL1 tumor syndrome usually requires pathogenic variants in both gene copies. One altered copy is not equivalent to the two-copy syndrome.',colon,[])}
for symbol,(name,summary,url,aliases) in extra.items():
 assert symbol not in [g['symbol'] for g in genes]
 genes.append({'symbol':symbol,'name':name,'summary':summary,'url':url,'source':'National Cancer Institute','conditions':[],'aliases':aliases,'reviewed':'','kind':'educational_summary'})
by={g['symbol']:g for g in genes}
for rank,(symbol,label) in enumerate(zip(order,focus),1):by[symbol].update(rank=rank,focus=label)
by['CDH1']['clinical_note']='An inherited pathogenic CDH1 variant can predispose to diffuse stomach cancer and lobular breast cancer. A variant of uncertain significance is not the same result. Specialist counseling may include discussion of stomach surveillance, risk-reducing surgery and breast screening, based on the confirmed variant and family history. A tumor-only CDH1 finding does not establish an inherited syndrome.'
by['CDH1']['clinical_source']=gastric
for symbol in ['BRCA1','BRCA2']:by[symbol]['clinical_source']='https://www.cancer.gov/about-cancer/causes-prevention/genetics/brca-fact-sheet'
for symbol in extra:by[symbol]['clinical_source']=by[symbol]['url']
for symbol in ['RAD51C','RAD51D']:by[symbol]['clinical_source']='https://dceg.cancer.gov/news-events/news/2021/breast-cancer-risk-genes'
for g in genes:
 g['slug']=re.sub(r'[^a-z0-9-]','-',g['symbol'].lower())
 assert g['url'].startswith('https://')
genes.sort(key=lambda g:(g.get('rank',9999),g['symbol']))
assert len({g['slug'] for g in genes})==len(genes)
(root/'dist/genetics-data.json').write_text(json.dumps(genes,ensure_ascii=False,separators=(',',':')))
index=[{k:g[k] for k in ['symbol','name','slug','aliases']}|{'rank':g.get('rank',9999),'focus':g.get('focus',''),'conditions':[c['name'] for c in g['conditions']]} for g in genes]
(root/'dist/genetics-index.js').write_text('window.geneDirectoryIndex='+json.dumps(index,ensure_ascii=False,separators=(',',':'))+';\n')
prov={'imported':'2026-09-28','source_url':'https://medlineplus.gov/download/ghr-summaries.xml','source_sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'medlineplus_gene_count':1500,'additional_nci_summaries':len(extra),'total_genes':len(genes),'recommended_reading_order':order,'ranking_basis':'Editorial order for cancer education, with CDH1 featured first at user request. Not a prevalence, severity, personal-risk or testing-priority ranking.','reuse_policy':'https://medlineplus.gov/about/using/usingcontent/','clinical_review':'New genetics content has not been individually signed off by Dr. Ehsan. Poster approval does not extend to this section.'}
(root/'data/genetics-provenance.json').write_text(json.dumps(prov,indent=2)+'\n')
top=''.join(f'<li><a href="?gene={symbol}#gene-{by[symbol]["slug"]}"><strong>{symbol}</strong> {h(label)}</a></li>' for symbol,label in zip(order,focus))
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Genes and Genetic Variants | Alex Ehsan, MD, PhD</title><meta name="description" content="Search gene names, aliases and related conditions. Start with CDH1 and a ranked reading list of hereditary cancer genes, or look up an exact variant in ClinVar."><link rel="canonical" href="https://dralexehsan.com/genetics.html"><link rel="stylesheet" href="genetics.css"></head><body><header><nav><a href="index.html">Alex Ehsan, MD, PhD</a><a href="index.html#library">Medical search</a><a href="#understand">Understand your result</a></nav></header><main><div class="intro"><p class="eyebrow">Free genetics education</p><h1>Find the gene.<br>Understand the difference.</h1><p>Search 1,510 genes by name, alias or related condition. Begin with CDH1, browse the hereditary cancer reading list, or explore the wider gene directory.</p></div><section aria-labelledby="search-title"><h2 id="search-title">Search genes and related conditions</h2><form id="gene-search-form" role="search"><label for="gene-search">Gene, alias or condition</label><div class="search-row"><input id="gene-search" type="search" placeholder="CDH1, BRCA2, HER2, Lynch syndrome…" autocomplete="off" aria-controls="gene-results"><button>Search</button></div></form><div class="controls"><label for="gene-view">Show</label><select id="gene-view"><option value="all">All 1,510 genes</option><option value="ranked">40 hereditary cancer starting points</option></select><label for="gene-sort">Order</label><select id="gene-sort"><option value="rank">Recommended reading order</option><option value="az">Gene name A to Z</option></select><button id="gene-clear" type="button">Clear search</button></div><p class="note">The numbered order is an editorial reading guide with CDH1 first. It does not rank cancer danger, mutation frequency, personal risk or which test you need.</p><p id="gene-count" role="status">Loading gene directory…</p><div id="gene-results" tabindex="-1"></div><button id="gene-more" type="button" hidden>Show more genes</button><noscript><p>Enable JavaScript to search all genes. The reading list and source links below remain available.</p></noscript></section><section id="variant-lookup" class="panel"><h2>Have an exact variant from a report?</h2><p>A gene can have many different variants. Look up the full gene and variant notation in NCBI ClinVar, then review the result with your genetics team. A missing or conflicting entry does not establish whether a variant is harmful.</p><form action="https://www.ncbi.nlm.nih.gov/clinvar/" method="get" target="_blank" rel="noopener noreferrer"><label for="variant-term">Gene and exact variant only</label><div class="search-row"><input id="variant-term" name="term" required placeholder="Example: BRCA1 c.68_69delAG"><button>Search ClinVar</button></div></form><p class="small">Opens the external ClinVar database. Do not enter names, dates of birth or medical records. This site does not classify variants or accept report uploads.</p><a href="https://www.ncbi.nlm.nih.gov/clinvar/docs/maintenance_use/">How to use ClinVar responsibly</a></section><section id="understand"><h2>What a genetic result can mean</h2><div class="explain-grid"><article class="panel"><h3>Inherited and tumor findings differ</h3><p>Germline testing looks for inherited susceptibility. Somatic testing examines changes in a tumor and may help guide cancer treatment. A tumor finding may need separate testing before it can be called inherited.</p></article><article class="panel"><h3>A variant is not always harmful</h3><p>Results may be pathogenic, likely pathogenic, uncertain, likely benign or benign. A variant of uncertain significance, or VUS, should not by itself drive preventive surgery or other changes in care. Family history still matters.</p></article><article class="panel"><h3>The exact result matters</h3><p>Ask which variant was found, whether one or both gene copies are affected, whether the finding is inherited, and what evidence supports its classification. A gene name alone is not a diagnosis.</p></article></div><p><a href="https://www.cancer.gov/about-cancer/causes-prevention/genetics/genetic-testing-fact-sheet">NCI guide to inherited cancer testing</a> · <a href="https://www.cancer.gov/about-cancer/treatment/types/biomarker-testing-cancer-treatment">NCI guide to tumor biomarker testing</a></p></section><section><h2>The 40-gene reading list</h2><p>These starting points concern specific disease-causing inherited variants. They do not describe every variant in each gene. Click a gene to read its overview and sources.</p><ol class="ranked-list">'''+top+'''</ol></section><footer><p>Educational only. Personal risk assessment, screening and treatment decisions require your own qualified healthcare team.</p><p>Source excerpts courtesy of MedlinePlus from the National Library of Medicine. Ten additional gene summaries use National Cancer Institute sources. Imported September 28, 2026. Individual source review dates vary and appear with each entry when supplied. This is a selected gene directory, not a complete catalog of all genes or mutations. Related condition links include different biological contexts and do not imply that every association is inherited.</p><p>New genetics content has not been individually reviewed by Dr. Ehsan. No NIH or NLM endorsement is implied.</p><a href="https://medlineplus.gov/about/developers/geneticsdatafilesapi/">Source data</a> · <a href="https://medlineplus.gov/genetics/">Full MedlinePlus Genetics library</a></footer></main><script src="genetics-index.js"></script><script src="genetics-search.js"></script><script src="genetics.js"></script></body></html>'''
(root/'dist/genetics.html').write_text(page)
print(json.dumps({'genes':len(genes),'ranked':len(order),'source_genes':1500,'additional_nci':len(extra)}))
